// TH14 v1.00b st05.ecl MainSub01:527-551 (entry) -> ECir00 / ECir00_at (dependency 14-47 / 49-81)
// Source type10 keeps target slot TH14_SHARD (native 0-23 keep slot); color 6 kept.
const TH14_SHARD: int = 512;

const TIME_LIMIT: int = 1724;   // 120 opening + 1600 source-window estimate + 4 startup margin
const OPENING_BUFFER: int = 120;

// etEx type4 ACCEL: a=120 frames, r=0.033333335 (1/30), s=F2-pi (fixed direction, expires).
xformdef FAN_ACCEL(gx: fx, gy: fx) {
    set_gravity(gx, gy);
    wait(120);
    set_gravity(0fx, 0fx);
}

// ECir00_at, source 49-81.
async sub ecir00_at(f2: angle, volleys: int) {
    wait(10);
    var rank: int = global(GVAR_RANK);
    var ways: int = 1;                          // !E 1
    if rank == 1 { ways = 3; }                  // !N 3
    if rank == 2 { ways = 5; }                  // !H 5
    if rank >= 3 { ways = 7; }                  // !LO 7 (Lunatic branch)
    // etAngle alpha = F2 - pi; acceleration vector r*(cos s, sin s), r = 1/30.
    var acc: angle = f2 - 180deg;
    var gx: fx = 0.033333335fx * cos(acc);
    var gy: fx = 0.033333335fx * sin(acc);
    var half: int = (ways - 1) / 2;
    for v in 0..volleys {
        // etAngle(0, F2 + RANDF2*0.17453292, 0.17453292): one signed draw per volley,
        // 0.17453292 rad = 1820 BAM.
        var u: fx = (rand(65536) - 32768) as fx / 32768;
        var off: int = (u * 1820fx) as int;
        var base: angle = f2 + (off as angle);
        for i in 0..ways {
            var a: angle = base + (((i - half) * 1820) as angle);
            // ANIM type2 a=1 birth retreat: position -= 4*velocity -> 8px back at speed 2.
            var bx: fx = $self_x - 8fx * cos(a);
            var by: fx = $self_y - 8fx * sin(a);
            _ = fire(TH14_SHARD, 6, bx, by, 2fx, a, FAN_ACCEL(gx, gy), none);
        }
        wait(4);
    }
}

// ECir00, source 14-47. Arguments are the creation snapshot of F0/F1/F2 and I0.
async sub ecir00(tx: fx, ty: fx, f2: angle, volleys: int) {
    set_invuln(65535);                          // training shell: no DPS
    set_hurtbox(12fx);                          // setHurtbox(24,24) -> radius 12
    set_hitbox(8fx);                            // setHitbox(16,16)  -> radius 8
    set_enemy_flag(ENEMY_NO_BODY, 1);           // flagSet(15) entry gate: body collision off
    // movePosRelTime(160, 1, F0, F1): mode1 = t^2 to the REL target over ABS (0, spawn_y).
    move_to(160, tx, ty, EASE_QUAD_IN);
    wait(160);
    set_enemy_flag(ENEMY_NO_BODY, 0);           // flagClear(15)
    spawn ecir00_at(f2, volleys);
    wait(120);
    // moveVel(ANGLE_PLAYER, 0.0f) + moveSpeedTime(120, 0, 3.0f)
    var dir: angle = aim_player();
    move_vel(0, dir, 0fx, EASE_LINEAR);
    move_speed(120, 3fx, EASE_LINEAR);
    loop { wait(1000); }
}

// MainSub01:527-551. Badge 1 starts at source frame 0, badge 2 at 430; both schedule 10.
async sub wave() {
    wait(OPENING_BUFFER);
    // Batch 1: F0 -160 (+32 before each create), F1 = RANDF2*32-96, spawn y 256, I0=1.
    var f0: fx = -160fx;
    var u1: fx = 0fx;
    var u2: fx = 0fx;
    var u3: fx = 0fx;
    var sx: fx = 0fx;
    var sy: fx = 0fx;
    for i in 0..10 {
        f0 = f0 + 32fx;
        u1 = (rand(65536) - 32768) as fx / 32768;   // F1 draw
        u2 = (rand(65536) - 32768) as fx / 32768;   // movePosRel x draw
        u3 = (rand(65536) - 32768) as fx / 32768;   // movePosRel y draw
        // enmCreate(0,256): FINAL = ABS + REL = (160+RANDF2*32, 256+RANDF2*64).
        sx = 160fx + u2 * 32fx;
        sy = 256fx + u3 * 64fx;
        _ = spawn_enemy(sx, sy, 160, 0, 0, 0,
            ecir00(f0, 256fx + (u1 * 32fx - 96fx), 49152bam, 1));
        wait(10);
    }
    wait(330);
    // Batch 2: F0 160 (-32 before each create), F1 = RANDF2*32-128, spawn y 192, I0=2.
    f0 = 160fx;
    for j in 0..10 {
        f0 = f0 - 32fx;
        u1 = (rand(65536) - 32768) as fx / 32768;
        u2 = (rand(65536) - 32768) as fx / 32768;
        u3 = (rand(65536) - 32768) as fx / 32768;
        sx = 160fx + u2 * 32fx;
        sy = 192fx + u3 * 64fx;
        _ = spawn_enemy(sx, sy, 160, 0, 0, 0,
            ecir00(f0, 192fx + (u1 * 32fx - 128fx), 49152bam, 2));
        wait(10);
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, wave, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
